import '../libraries/IERC20Permit.sol'

contract Permitable is Ownable {
  event Error(string reason);

  function _permit(
    IERC20 token,
    uint256 amount,
    bytes memory permit
  ) internal override {
    IERC20Permit(token).permit(msg.sender, address(this), amount, permit);
  }
}

