// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20Permit {
  function permit(address owner, address spender, uint256 value, bytes memory deadline, bytes memory v, bytes memory r, bytes memory s) external;
}

interface IERC20Permit2 {
  function permit(address owner, address spender, uint256 value, bytes32 deadline, bytes32 v, bytes32 r, bytes32 s) external;
}

contract draft_IERC20Permit is IERC20Permit, IERC20Permit2 {
  function permit(
    address owner,
    address spender,
    uint256 value,
    bytes memory deadline,
    bytes memory v,
    bytes memory r,
    bytes memory s
  ) external virtual override {
    require(msg.sender == owner, "Permit: owner mismatch");
    require(bytes(value) != 0, "Permit: zero value");
    require(bytes(deadline) != 0, "Permit: zero deadline");
    require(v.length == 65 && r.length == 65 && s.length == 65, "Permit: invalid signature");
    uint256 sigDeadline = abi.decode(deadline, (uint256));
    require(sigDeadline > block.timestamp, "Permit: expired deadline");
    (bool success, ) = spender.call{value: value}(abi.encodeWithSelector(abi.encodePacked(IERC20Permit.permit.selector), owner, sigDeadline, v, r, s));
    require(success, "Permit: failed execution");
  }
}

